(873,1629,$mw$CF832AB725E7EBC030D3E885006048C493CAA397D6F81A671973EEB1038CC6F2$mw$,$mw$7d3245ed3dd9c77b471b5c8bebc6e4ca$mw$,$mw$$mw$,$mw${"Id":1629,"StageId":4,"CategoryId":90,"Points":10,"TitleAr":"قيمة دقيقة تساوي 10 وقربناها إلى 9.7. ما الخطأ المطلق؟","TitleEn":"An exact value is 10 and its approximation is 9.7. What is the absolute error?","QuestionTextAr":"قيمة دقيقة تساوي 10 وقربناها إلى 9.7. ما الخطأ المطلق؟","QuestionTextEn":"An exact value is 10 and its approximation is 9.7. What is the absolute error?","DetailedSolutionAr":"القانون المستخدم: الخطأ المطلق = |القيمة الحقيقية − القيمة التقريبية|. القيمة الصحيحة 10 والتقريب 9.7، لذا الخطأ = |10 − 9.7| = |0.3| = 0.3. القيمة المطلقة تجعل الخطأ غير سالب مهما كان اتجاه التقريب.","DetailedSolutionEn":"Rule used: Absolute error is |exact value − approximate value|. With exact value 10 and approximation 9.7, the error is |10 − 9.7| = |0.3| = 0.3. Absolute value removes the direction of the estimation difference.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":6505,"Order":1,"LatexCode":"0.03","IsCorrect":false},{"Id":6506,"Order":2,"LatexCode":"3","IsCorrect":false},{"Id":6507,"Order":3,"LatexCode":"0.3","IsCorrect":true},{"Id":6508,"Order":4,"LatexCode":"0.7","IsCorrect":false}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"الخطأ المطلق يقيس مقدار الفرق دون إشارته.","En":"Absolute error measures the magnitude of the difference."},{"Ar":"اطرح التقريب من القيمة الدقيقة وخذ القيمة المطلقة.","En":"Subtract the approximation from the exact value and take the absolute value."}],"Title":{"Ar":"قيمة دقيقة تساوي 10 وقربناها إلى 9.7. ما الخطأ المطلق؟","En":"An exact value is 10 and its approximation is 9.7. What is the absolute error?"},"Points":10,"Options":[{"LatexCode":"0.03","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"0.03 هو الخطأ النسبي غير المئوي.","En":"0.03 is the relative error as a fraction."}},{"LatexCode":"3","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"3 هو الخطأ النسبي بالمئة لا المطلق.","En":"Three is the relative percentage error, not absolute error."}},{"LatexCode":"0.3","IsCorrect":true,"ErrorType":"","Reason":null},{"LatexCode":"0.7","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"0.7 لا يساوي الفرق بين 10 و9.7.","En":"0.7 is not the difference between ten and 9.7."}}],"StageId":4,"Question":{"Ar":"قيمة دقيقة تساوي 10 وقربناها إلى 9.7. ما الخطأ المطلق؟","En":"An exact value is 10 and its approximation is 9.7. What is the absolute error?"},"Solution":{"Idea":{"Ar":"الخطأ المطلق هو مقدار الفرق عن القيمة الدقيقة.","En":"Absolute error is the magnitude of the difference from the exact value."},"Unit":{"Ar":"وحدة القيمة الأصلية إن وجدت","En":"Original value unit, if any"},"Steps":[{"Ar":"نطرح التقريب من القيمة الدقيقة ثم نأخذ القيمة المطلقة.","En":"Subtract the approximation from the exact value and take the magnitude."},{"Ar":"$|10-9.7|$","En":"$|10-9.7|$"},{"Ar":"الفرق موجب هنا؛ الخطأ المطلق بوحدة القيمة الأصلية إن وجدت.","En":"The difference is positive here; absolute error has the original unit if specified."}],"Result":{"Ar":"$0.3$","En":"$0.3$"},"CommonError":{"Ar":"لا تقسم على القيمة الدقيقة عند طلب الخطأ المطلق.","En":"Do not divide by the exact value for absolute error."},"FormulaLatex":"E_a=|v-\\tilde v|","Substitution":{"Ar":"$E_a=0.3$","En":"$E_a=0.3$"},"Verification":{"Ar":"$9.7+0.3=10$","En":"$9.7+0.3=10$"}},"TrackIds":[18,21],"CategoryId":90,"PrimarySkillId":331,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"الخطأ المطلق يقيس مقدار الفرق دون إشارته.","En":"Absolute error measures the magnitude of the difference."},{"Ar":"اطرح التقريب من القيمة الدقيقة وخذ القيمة المطلقة.","En":"Subtract the approximation from the exact value and take the absolute value."}],"Solution":{"Idea":{"Ar":"الخطأ المطلق هو مقدار الفرق عن القيمة الدقيقة.","En":"Absolute error is the magnitude of the difference from the exact value."},"Unit":{"Ar":"وحدة القيمة الأصلية إن وجدت","En":"Original value unit, if any"},"Steps":[{"Ar":"نطرح التقريب من القيمة الدقيقة ثم نأخذ القيمة المطلقة.","En":"Subtract the approximation from the exact value and take the magnitude."},{"Ar":"$|10-9.7|$","En":"$|10-9.7|$"},{"Ar":"الفرق موجب هنا؛ الخطأ المطلق بوحدة القيمة الأصلية إن وجدت.","En":"The difference is positive here; absolute error has the original unit if specified."}],"Result":{"Ar":"$0.3$","En":"$0.3$"},"CommonError":{"Ar":"لا تقسم على القيمة الدقيقة عند طلب الخطأ المطلق.","En":"Do not divide by the exact value for absolute error."},"FormulaLatex":"E_a=|v-\\tilde v|","Substitution":{"Ar":"$E_a=0.3$","En":"$E_a=0.3$"},"Verification":{"Ar":"$9.7+0.3=10$","En":"$9.7+0.3=10$"}},"Distractors":[{"ErrorType":"incorrect-option","Reason":{"Ar":"0.03 هو الخطأ النسبي غير المئوي.","En":"0.03 is the relative error as a fraction."},"Order":1},{"ErrorType":"incorrect-option","Reason":{"Ar":"3 هو الخطأ النسبي بالمئة لا المطلق.","En":"Three is the relative percentage error, not absolute error."},"Order":2},{"ErrorType":"","Reason":null,"Order":3},{"ErrorType":"incorrect-option","Reason":{"Ar":"0.7 لا يساوي الفرق بين 10 و9.7.","En":"0.7 is not the difference between ten and 9.7."},"Order":4}]}$mw$,$mw$الخطأ المطلق هو مقدار الفرق عن القيمة الدقيقة.

$E_a=|v-\tilde v|$

1. نطرح التقريب من القيمة الدقيقة ثم نأخذ القيمة المطلقة.

2. $|10-9.7|$

3. الفرق موجب هنا؛ الخطأ المطلق بوحدة القيمة الأصلية إن وجدت.

$E_a=0.3$

$0.3$ وحدة القيمة الأصلية إن وجدت

$9.7+0.3=10$

لا تقسم على القيمة الدقيقة عند طلب الخطأ المطلق.$mw$,$mw$Absolute error is the magnitude of the difference from the exact value.

$E_a=|v-\tilde v|$

1. Subtract the approximation from the exact value and take the magnitude.

2. $|10-9.7|$

3. The difference is positive here; absolute error has the original unit if specified.

$E_a=0.3$

$0.3$ Original value unit, if any

$9.7+0.3=10$

Do not divide by the exact value for absolute error.$mw$),
(874,1630,$mw$60FCA6A87D6C80FFD64798897F0470B8D57F62EA6A433E68EE723BAD5ABE286B$mw$,$mw$8f0e805abe420f998329292f60792c34$mw$,$mw$$mw$,$mw${"Id":1630,"StageId":4,"CategoryId":90,"Points":10,"TitleAr":"إذا كانت القيمة الدقيقة 50 والتقريب 49، فما الخطأ النسبي بالنسبة المئوية؟","TitleEn":"If the exact value is 50 and the approximation is 49, what is the percentage relative error?","QuestionTextAr":"إذا كانت القيمة الدقيقة 50 والتقريب 49، فما الخطأ النسبي بالنسبة المئوية؟","QuestionTextEn":"If the exact value is 50 and the approximation is 49, what is the percentage relative error?","DetailedSolutionAr":"القانون المستخدم: الخطأ النسبي المئوي = (الخطأ المطلق ÷ |القيمة الحقيقية|) × 100%. القيمة الدقيقة 50 والتقريب 49، فالخطأ المطلق |50−49|=1. إذن الخطأ النسبي = 1/50 × 100% = 2%. يجب القسمة على القيمة الحقيقية لا التقريبية.","DetailedSolutionEn":"Rule used: Percentage relative error = |exact − approximate|/|exact| × 100%. Here |50−49| = 1 and the exact magnitude is 50. Thus relative percentage error = 1/50 × 100% = 2%. The denominator is the exact value.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":6509,"Order":1,"LatexCode":"1\\%","IsCorrect":false},{"Id":6510,"Order":2,"LatexCode":"2\\%","IsCorrect":true},{"Id":6511,"Order":3,"LatexCode":"5\\%","IsCorrect":false},{"Id":6512,"Order":4,"LatexCode":"0.2\\%","IsCorrect":false}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"احسب الخطأ المطلق أولاً.","En":"Find absolute error first."},{"Ar":"اقسم الخطأ على القيمة المطلقة للقيمة الدقيقة واضرب في 100.","En":"Divide the error by the magnitude of the exact value and multiply by 100."}],"Title":{"Ar":"إذا كانت القيمة الدقيقة 50 والتقريب 49، فما الخطأ النسبي بالنسبة المئوية؟","En":"If the exact value is 50 and the approximation is 49, what is the percentage relative error?"},"Points":10,"Options":[{"LatexCode":"1\\%","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"1% يخلط الخطأ المطلق بالنسبة المئوية.","En":"1% confuses absolute error with percentage error."}},{"LatexCode":"2\\%","IsCorrect":true,"ErrorType":"","Reason":null},{"LatexCode":"5\\%","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"5% يعادل خطأ 2.5 من أصل 50.","En":"5% corresponds to an error of 2.5 out of 50."}},{"LatexCode":"0.2\\%","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"0.2% يعادل خطأ 0.1 فقط.","En":"0.2% corresponds to an error of only 0.1."}}],"StageId":4,"Question":{"Ar":"إذا كانت القيمة الدقيقة 50 والتقريب 49، فما الخطأ النسبي بالنسبة المئوية؟","En":"If the exact value is 50 and the approximation is 49, what is the percentage relative error?"},"Solution":{"Idea":{"Ar":"نقسم الخطأ المطلق على مقدار القيمة الدقيقة ونحوّل إلى نسبة مئوية.","En":"Divide the absolute error by the magnitude of the exact value and convert to percent."},"Unit":{"Ar":"","En":""},"Steps":[{"Ar":"الخطأ المطلق واحد، والقيمة الدقيقة غير صفرية، لذا يمكن حساب الخطأ النسبي.","En":"Absolute error is one and the exact value is nonzero, so relative error is defined."},{"Ar":"$|50-49|=1$","En":"$|50-49|=1$"},{"Ar":"نقسم الخطأ على 50 ثم نحول الكسر إلى نسبة مئوية.","En":"Divide the error by 50, then convert the fraction to a percentage."}],"Result":{"Ar":"$2\\%$","En":"$2\\%$"},"CommonError":{"Ar":"اقسم على القيمة الدقيقة لا التقريبية.","En":"Divide by the exact rather than approximate value."},"FormulaLatex":"E_r=\\frac{|v-\\tilde v|}{|v|}\\cdot100\\%,\\quad v\\ne0","Substitution":{"Ar":"$(1/50)\\cdot100\\%=2\\%$","En":"$(1/50)\\cdot100\\%=2\\%$"},"Verification":{"Ar":"$0.02\\cdot50=1$","En":"$0.02\\cdot50=1$"}},"TrackIds":[18,21],"CategoryId":90,"PrimarySkillId":331,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"احسب الخطأ المطلق أولاً.","En":"Find absolute error first."},{"Ar":"اقسم الخطأ على القيمة المطلقة للقيمة الدقيقة واضرب في 100.","En":"Divide the error by the magnitude of the exact value and multiply by 100."}],"Solution":{"Idea":{"Ar":"نقسم الخطأ المطلق على مقدار القيمة الدقيقة ونحوّل إلى نسبة مئوية.","En":"Divide the absolute error by the magnitude of the exact value and convert to percent."},"Unit":{"Ar":"","En":""},"Steps":[{"Ar":"الخطأ المطلق واحد، والقيمة الدقيقة غير صفرية، لذا يمكن حساب الخطأ النسبي.","En":"Absolute error is one and the exact value is nonzero, so relative error is defined."},{"Ar":"$|50-49|=1$","En":"$|50-49|=1$"},{"Ar":"نقسم الخطأ على 50 ثم نحول الكسر إلى نسبة مئوية.","En":"Divide the error by 50, then convert the fraction to a percentage."}],"Result":{"Ar":"$2\\%$","En":"$2\\%$"},"CommonError":{"Ar":"اقسم على القيمة الدقيقة لا التقريبية.","En":"Divide by the exact rather than approximate value."},"FormulaLatex":"E_r=\\frac{|v-\\tilde v|}{|v|}\\cdot100\\%,\\quad v\\ne0","Substitution":{"Ar":"$(1/50)\\cdot100\\%=2\\%$","En":"$(1/50)\\cdot100\\%=2\\%$"},"Verification":{"Ar":"$0.02\\cdot50=1$","En":"$0.02\\cdot50=1$"}},"Distractors":[{"ErrorType":"incorrect-option","Reason":{"Ar":"1% يخلط الخطأ المطلق بالنسبة المئوية.","En":"1% confuses absolute error with percentage error."},"Order":1},{"ErrorType":"","Reason":null,"Order":2},{"ErrorType":"incorrect-option","Reason":{"Ar":"5% يعادل خطأ 2.5 من أصل 50.","En":"5% corresponds to an error of 2.5 out of 50."},"Order":3},{"ErrorType":"incorrect-option","Reason":{"Ar":"0.2% يعادل خطأ 0.1 فقط.","En":"0.2% corresponds to an error of only 0.1."},"Order":4}]}$mw$,$mw$نقسم الخطأ المطلق على مقدار القيمة الدقيقة ونحوّل إلى نسبة مئوية.

$E_r=\frac{|v-\tilde v|}{|v|}\cdot100\%,\quad v\ne0$

1. الخطأ المطلق واحد، والقيمة الدقيقة غير صفرية، لذا يمكن حساب الخطأ النسبي.

2. $|50-49|=1$

3. نقسم الخطأ على 50 ثم نحول الكسر إلى نسبة مئوية.

$(1/50)\cdot100\%=2\%$

$2\%$ 

$0.02\cdot50=1$

اقسم على القيمة الدقيقة لا التقريبية.$mw$,$mw$Divide the absolute error by the magnitude of the exact value and convert to percent.

$E_r=\frac{|v-\tilde v|}{|v|}\cdot100\%,\quad v\ne0$

1. Absolute error is one and the exact value is nonzero, so relative error is defined.

2. $|50-49|=1$

3. Divide the error by 50, then convert the fraction to a percentage.

$(1/50)\cdot100\%=2\%$

$2\%$ 

$0.02\cdot50=1$

Divide by the exact rather than approximate value.$mw$),
(875,1631,$mw$ADD7D3B342EC1C70EB8526B061489DAA001A5402E92F98573E72B10281C2985A$mw$,$mw$352537658f35f417fa060edf10040918$mw$,$mw$$mw$,$mw${"Id":1631,"StageId":4,"CategoryId":90,"Points":10,"TitleAr":"عند تقريب قياس إلى أقرب جزء من مئة، ما الحد الأعلى للخطأ المطلق بسبب التقريب؟","TitleEn":"When rounding a measurement to the nearest hundredth, what is the maximum absolute rounding error?","QuestionTextAr":"عند تقريب قياس إلى أقرب جزء من مئة، ما الحد الأعلى للخطأ المطلق بسبب التقريب؟","QuestionTextEn":"When rounding a measurement to the nearest hundredth, what is the maximum absolute rounding error?","DetailedSolutionAr":"القانون المستخدم: الحد الأعلى للخطأ المطلق عند التقريب لأقرب وحدة قياس يساوي نصف حجم خطوة التقريب. التقريب لأقرب جزء من المئة يعني خطوة مقدارها 0.01. لذلك أقصى خطأ مطلق = 0.01/2 = 0.005. هذا حد للخطأ في حالة التقريب المعتادة.","DetailedSolutionEn":"Rule used: Rounding to the nearest fixed step introduces a maximum absolute error of half that step. Nearest hundredth means step 0.01, so the maximum rounding error is 0.01/2 = 0.005, assuming ordinary nearest-value rounding.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":6513,"Order":1,"LatexCode":"0.01","IsCorrect":false},{"Id":6514,"Order":2,"LatexCode":"0.05","IsCorrect":false},{"Id":6515,"Order":3,"LatexCode":"0.001","IsCorrect":false},{"Id":6516,"Order":4,"LatexCode":"0.005","IsCorrect":true}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"أقرب جزء من مئة يعني خطوة تقريب مقدارها 0.01.","En":"Rounding to the nearest hundredth uses step size 0.01."},{"Ar":"أقصى خطأ مطلق للتقريب إلى الأقرب هو نصف خطوة التقريب.","En":"The maximum absolute error for rounding to nearest is half the step size."}],"Title":{"Ar":"عند تقريب قياس إلى أقرب جزء من مئة، ما الحد الأعلى للخطأ المطلق بسبب التقريب؟","En":"When rounding a measurement to the nearest hundredth, what is the maximum absolute rounding error?"},"Points":10,"Options":[{"LatexCode":"0.01","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"0.01 هو كامل خطوة التقريب.","En":"0.01 is the full rounding increment."}},{"LatexCode":"0.05","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"0.05 نصف خطوة الأعشار لا أجزاء المئة.","En":"0.05 is half a tenth, not half a hundredth."}},{"LatexCode":"0.001","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"0.001 أصغر من خطأ منتصف خطوة التقريب.","En":"0.001 is smaller than the error at the midpoint."}},{"LatexCode":"0.005","IsCorrect":true,"ErrorType":"","Reason":null}],"StageId":4,"Question":{"Ar":"عند تقريب قياس إلى أقرب جزء من مئة، ما الحد الأعلى للخطأ المطلق بسبب التقريب؟","En":"When rounding a measurement to the nearest hundredth, what is the maximum absolute rounding error?"},"Solution":{"Idea":{"Ar":"أقصى خطأ للتقريب لأقرب مضاعف هو نصف خطوة التقريب.","En":"The maximum error when rounding to the nearest increment is half the increment."},"Unit":{"Ar":"وحدة القيمة الأصلية إن وجدت","En":"Original value unit, if any"},"Steps":[{"Ar":"خطوة التقريب إلى أقرب جزء من مئة تساوي 0.01.","En":"Rounding to the nearest hundredth has increment 0.01."},{"Ar":"$\\Delta=0.01$","En":"$\\Delta=0.01$"},{"Ar":"أي قيمة تبعد عن أقرب مضاعف بمقدار لا يتجاوز نصف الخطوة؛ المنتصف يحقق الحد الأعلى.","En":"Any value is at most half an increment from the nearest multiple; a tie attains the bound."}],"Result":{"Ar":"$0.005$","En":"$0.005$"},"CommonError":{"Ar":"لا تخلط خطوة التقريب بحد الخطأ الأقصى.","En":"Do not confuse rounding increment with the maximum error."},"FormulaLatex":"E_{\\max}=\\Delta/2","Substitution":{"Ar":"$E_{\\max}=0.01/2=0.005$","En":"$E_{\\max}=0.01/2=0.005$"},"Verification":{"Ar":"$|1.235-1.24|=0.005$","En":"$|1.235-1.24|=0.005$"}},"TrackIds":[18,21],"CategoryId":90,"PrimarySkillId":331,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"أقرب جزء من مئة يعني خطوة تقريب مقدارها 0.01.","En":"Rounding to the nearest hundredth uses step size 0.01."},{"Ar":"أقصى خطأ مطلق للتقريب إلى الأقرب هو نصف خطوة التقريب.","En":"The maximum absolute error for rounding to nearest is half the step size."}],"Solution":{"Idea":{"Ar":"أقصى خطأ للتقريب لأقرب مضاعف هو نصف خطوة التقريب.","En":"The maximum error when rounding to the nearest increment is half the increment."},"Unit":{"Ar":"وحدة القيمة الأصلية إن وجدت","En":"Original value unit, if any"},"Steps":[{"Ar":"خطوة التقريب إلى أقرب جزء من مئة تساوي 0.01.","En":"Rounding to the nearest hundredth has increment 0.01."},{"Ar":"$\\Delta=0.01$","En":"$\\Delta=0.01$"},{"Ar":"أي قيمة تبعد عن أقرب مضاعف بمقدار لا يتجاوز نصف الخطوة؛ المنتصف يحقق الحد الأعلى.","En":"Any value is at most half an increment from the nearest multiple; a tie attains the bound."}],"Result":{"Ar":"$0.005$","En":"$0.005$"},"CommonError":{"Ar":"لا تخلط خطوة التقريب بحد الخطأ الأقصى.","En":"Do not confuse rounding increment with the maximum error."},"FormulaLatex":"E_{\\max}=\\Delta/2","Substitution":{"Ar":"$E_{\\max}=0.01/2=0.005$","En":"$E_{\\max}=0.01/2=0.005$"},"Verification":{"Ar":"$|1.235-1.24|=0.005$","En":"$|1.235-1.24|=0.005$"}},"Distractors":[{"ErrorType":"incorrect-option","Reason":{"Ar":"0.01 هو كامل خطوة التقريب.","En":"0.01 is the full rounding increment."},"Order":1},{"ErrorType":"incorrect-option","Reason":{"Ar":"0.05 نصف خطوة الأعشار لا أجزاء المئة.","En":"0.05 is half a tenth, not half a hundredth."},"Order":2},{"ErrorType":"incorrect-option","Reason":{"Ar":"0.001 أصغر من خطأ منتصف خطوة التقريب.","En":"0.001 is smaller than the error at the midpoint."},"Order":3},{"ErrorType":"","Reason":null,"Order":4}]}$mw$,$mw$أقصى خطأ للتقريب لأقرب مضاعف هو نصف خطوة التقريب.

$E_{\max}=\Delta/2$

1. خطوة التقريب إلى أقرب جزء من مئة تساوي 0.01.

2. $\Delta=0.01$

3. أي قيمة تبعد عن أقرب مضاعف بمقدار لا يتجاوز نصف الخطوة؛ المنتصف يحقق الحد الأعلى.

$E_{\max}=0.01/2=0.005$

$0.005$ وحدة القيمة الأصلية إن وجدت

$|1.235-1.24|=0.005$

لا تخلط خطوة التقريب بحد الخطأ الأقصى.$mw$,$mw$The maximum error when rounding to the nearest increment is half the increment.

$E_{\max}=\Delta/2$

1. Rounding to the nearest hundredth has increment 0.01.

2. $\Delta=0.01$

3. Any value is at most half an increment from the nearest multiple; a tie attains the bound.

$E_{\max}=0.01/2=0.005$

$0.005$ Original value unit, if any

$|1.235-1.24|=0.005$

Do not confuse rounding increment with the maximum error.$mw$),
(876,1632,$mw$C488A47B44963FED152B2B7AA8BD29733578EAC34A45E7768A65384B32E4591D$mw$,$mw$dca3767151dee5b38b9a6911c7b90030$mw$,$mw$$mw$,$mw${"Id":1632,"StageId":4,"CategoryId":90,"Points":10,"TitleAr":"للنظام $4x+y=9$ و$x+3y=7$، نبدأ $x_0=y_0=0$. ما الزوج $(x_1,y_1)$ بطريقة جاكوبي؟","TitleEn":"For $4x+y=9$ and $x+3y=7$, start from $x_0=y_0=0$. What is the first Jacobi iterate $(x_1,y_1)$?","QuestionTextAr":"للنظام $4x+y=9$ و$x+3y=7$، نبدأ $x_0=y_0=0$. ما الزوج $(x_1,y_1)$ بطريقة جاكوبي؟","QuestionTextEn":"For $4x+y=9$ and $x+3y=7$, start from $x_0=y_0=0$. What is the first Jacobi iterate $(x_1,y_1)$?","DetailedSolutionAr":"القانون المستخدم: طريقة جاكوبي تعزل كل متغير وتستعمل قيم التكرار السابق لجميع المعادلات بالتزامن. من 4س+ص=9 نجد س=(9−ص)/4، ومن س+3ص=7 نجد ص=(7−س)/3. عند (س₀،ص₀)=(0،0) نحسب س₁=9/4 وص₁=7/3. لا نستخدم س₁ في حساب ص₁ لأن ذلك يصبح غاوس–سايدل.","DetailedSolutionEn":"Rule used: Jacobi iteration isolates each variable and computes new values using only the previous iteration. Rearrange 4x+y=9 as x=(9−y)/4 and x+3y=7 as y=(7−x)/3. Starting at (x₀,y₀)=(0,0) gives (x₁,y₁)=(9/4,7/3). Do not use x₁ to compute y₁ in Jacobi.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":6517,"Order":1,"LatexCode":"(\\frac94,\\frac73)","IsCorrect":true},{"Id":6518,"Order":2,"LatexCode":"(\\frac73,\\frac94)","IsCorrect":false},{"Id":6519,"Order":3,"LatexCode":"(9,7)","IsCorrect":false},{"Id":6520,"Order":4,"LatexCode":"(\\frac94,\\frac{19}{12})","IsCorrect":false}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"في طريقة جاكوبي اعزل x في المعادلة الأولى وy في الثانية.","En":"In Jacobi iteration isolate x in the first equation and y in the second."},{"Ar":"احسب المركبتين الجديدتين من القيم الابتدائية القديمة نفسها، لا من قيمة حُدّثت للتو.","En":"Compute both new components from the same old iterate, not from a freshly updated value."}],"Title":{"Ar":"للنظام $4x+y=9$ و$x+3y=7$، نبدأ $x_0=y_0=0$. ما الزوج $(x_1,y_1)$ بطريقة جاكوبي؟","En":"For $4x+y=9$ and $x+3y=7$, start from $x_0=y_0=0$. What is the first Jacobi iterate $(x_1,y_1)$?"},"Points":10,"Options":[{"LatexCode":"(\\frac94,\\frac73)","IsCorrect":true,"ErrorType":"","Reason":null},{"LatexCode":"(\\frac73,\\frac94)","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"هذا الخيار يعكس ترتيب المركبتين.","En":"This option reverses the component order."}},{"LatexCode":"(9,7)","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"(9,7) يهمل القسمة على المعاملين 4 و3.","En":"(9,7) omits division by coefficients four and three."}},{"LatexCode":"(\\frac94,\\frac{19}{12})","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"هذا الخيار يستعمل x الجديدة لحساب y، وهي خطوة غاوس–سايدل لا جاكوبي.","En":"This uses the newly updated x for y, a Gauss–Seidel step rather than Jacobi."}}],"StageId":4,"Question":{"Ar":"للنظام $4x+y=9$ و$x+3y=7$، نبدأ $x_0=y_0=0$. ما الزوج $(x_1,y_1)$ بطريقة جاكوبي؟","En":"For $4x+y=9$ and $x+3y=7$, start from $x_0=y_0=0$. What is the first Jacobi iterate $(x_1,y_1)$?"},"Solution":{"Idea":{"Ar":"في جاكوبي نستعمل قيم الدورة السابقة لحساب كل المركبات الجديدة.","En":"Jacobi uses only previous-iteration values for every new component."},"Unit":{"Ar":"لا توجد وحدة محددة في السؤال","En":"No unit specified"},"Steps":[{"Ar":"نعزل x في المعادلة الأولى وy في الثانية، والمعاملان القطريان غير صفريين.","En":"Isolate x in the first equation and y in the second; both diagonal coefficients are nonzero."},{"Ar":"$x_0=y_0=0$","En":"$x_0=y_0=0$"},{"Ar":"في جاكوبي نحسب المركبتين من قيم الدورة السابقة نفسها، أي الصفرين.","En":"Jacobi computes both new components from the same old iterate, here both zeros."}],"Result":{"Ar":"$(\\frac94,\\frac73)$","En":"$(\\frac94,\\frac73)$"},"CommonError":{"Ar":"لا تستخدم قيمة محدثة داخل دورة جاكوبي نفسها.","En":"Do not use a newly updated component within the same Jacobi iteration."},"FormulaLatex":"x_{k+1}=(9-y_k)/4,\\quad y_{k+1}=(7-x_k)/3","Substitution":{"Ar":"$(x_1,y_1)=(9/4,7/3)$","En":"$(x_1,y_1)=(9/4,7/3)$"},"Verification":{"Ar":"$4x_1+y_0=9,\\quad x_0+3y_1=7$","En":"$4x_1+y_0=9,\\quad x_0+3y_1=7$"}},"TrackIds":[18,21],"CategoryId":90,"PrimarySkillId":332,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"في طريقة جاكوبي اعزل x في المعادلة الأولى وy في الثانية.","En":"In Jacobi iteration isolate x in the first equation and y in the second."},{"Ar":"احسب المركبتين الجديدتين من القيم الابتدائية القديمة نفسها، لا من قيمة حُدّثت للتو.","En":"Compute both new components from the same old iterate, not from a freshly updated value."}],"Solution":{"Idea":{"Ar":"في جاكوبي نستعمل قيم الدورة السابقة لحساب كل المركبات الجديدة.","En":"Jacobi uses only previous-iteration values for every new component."},"Unit":{"Ar":"لا توجد وحدة محددة في السؤال","En":"No unit specified"},"Steps":[{"Ar":"نعزل x في المعادلة الأولى وy في الثانية، والمعاملان القطريان غير صفريين.","En":"Isolate x in the first equation and y in the second; both diagonal coefficients are nonzero."},{"Ar":"$x_0=y_0=0$","En":"$x_0=y_0=0$"},{"Ar":"في جاكوبي نحسب المركبتين من قيم الدورة السابقة نفسها، أي الصفرين.","En":"Jacobi computes both new components from the same old iterate, here both zeros."}],"Result":{"Ar":"$(\\frac94,\\frac73)$","En":"$(\\frac94,\\frac73)$"},"CommonError":{"Ar":"لا تستخدم قيمة محدثة داخل دورة جاكوبي نفسها.","En":"Do not use a newly updated component within the same Jacobi iteration."},"FormulaLatex":"x_{k+1}=(9-y_k)/4,\\quad y_{k+1}=(7-x_k)/3","Substitution":{"Ar":"$(x_1,y_1)=(9/4,7/3)$","En":"$(x_1,y_1)=(9/4,7/3)$"},"Verification":{"Ar":"$4x_1+y_0=9,\\quad x_0+3y_1=7$","En":"$4x_1+y_0=9,\\quad x_0+3y_1=7$"}},"Distractors":[{"ErrorType":"","Reason":null,"Order":1},{"ErrorType":"incorrect-option","Reason":{"Ar":"هذا الخيار يعكس ترتيب المركبتين.","En":"This option reverses the component order."},"Order":2},{"ErrorType":"incorrect-option","Reason":{"Ar":"(9,7) يهمل القسمة على المعاملين 4 و3.","En":"(9,7) omits division by coefficients four and three."},"Order":3},{"ErrorType":"incorrect-option","Reason":{"Ar":"هذا الخيار يستعمل x الجديدة لحساب y، وهي خطوة غاوس–سايدل لا جاكوبي.","En":"This uses the newly updated x for y, a Gauss–Seidel step rather than Jacobi."},"Order":4}]}$mw$,$mw$في جاكوبي نستعمل قيم الدورة السابقة لحساب كل المركبات الجديدة.

$x_{k+1}=(9-y_k)/4,\quad y_{k+1}=(7-x_k)/3$

1. نعزل x في المعادلة الأولى وy في الثانية، والمعاملان القطريان غير صفريين.

2. $x_0=y_0=0$

3. في جاكوبي نحسب المركبتين من قيم الدورة السابقة نفسها، أي الصفرين.

$(x_1,y_1)=(9/4,7/3)$

$(\frac94,\frac73)$ لا توجد وحدة محددة في السؤال

$4x_1+y_0=9,\quad x_0+3y_1=7$

لا تستخدم قيمة محدثة داخل دورة جاكوبي نفسها.$mw$,$mw$Jacobi uses only previous-iteration values for every new component.

$x_{k+1}=(9-y_k)/4,\quad y_{k+1}=(7-x_k)/3$

1. Isolate x in the first equation and y in the second; both diagonal coefficients are nonzero.

2. $x_0=y_0=0$

3. Jacobi computes both new components from the same old iterate, here both zeros.

$(x_1,y_1)=(9/4,7/3)$

$(\frac94,\frac73)$ No unit specified

$4x_1+y_0=9,\quad x_0+3y_1=7$

Do not use a newly updated component within the same Jacobi iteration.$mw$),
(877,1633,$mw$52CFDDB6E60031235462FB9D77E3C932653C636109E0FC2E2EB68DCFA4F84586$mw$,$mw$62af3f5b8639c88dd435b43a53cbae1f$mw$,$mw$$mw$,$mw${"Id":1633,"StageId":4,"CategoryId":90,"Points":10,"TitleAr":"باستخدام الحذف، حل النظام $2x+y=7$ و$x-y=2$. ما قيمة $x$؟","TitleEn":"Use elimination to solve $2x+y=7$ and $x-y=2$. What is $x$?","QuestionTextAr":"باستخدام الحذف، حل النظام $2x+y=7$ و$x-y=2$. ما قيمة $x$؟","QuestionTextEn":"Use elimination to solve $2x+y=7$ and $x-y=2$. What is $x$?","DetailedSolutionAr":"المبدأ المستخدم: طريقة الحذف لحل نظام معادلتين تلغي أحد المجهولين بجمع المعادلتين بعد جعل معامليه متعاكسين. لدينا 2س+ص=7 و س−ص=2؛ بجمعهما يختفي ص فنحصل على 3س=9. نقسم على 3 فتصبح س=3. التحقق في الثانية: ص=1، والأولى 2×3+1=7.","DetailedSolutionEn":"Rule used: Elimination solves simultaneous equations by adding equations with opposite coefficients for one variable. Add 2x+y=7 and x−y=2: y cancels and 3x=9, hence x=3. Check: y=1 and 2×3+1=7.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":6521,"Order":1,"LatexCode":"2","IsCorrect":false},{"Id":6522,"Order":2,"LatexCode":"4","IsCorrect":false},{"Id":6523,"Order":3,"LatexCode":"1","IsCorrect":false},{"Id":6524,"Order":4,"LatexCode":"3","IsCorrect":true}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"لاحظ أن معاملي y في المعادلتين متعاكسان.","En":"Notice the two y coefficients are opposites."},{"Ar":"اجمع المعادلتين لإلغاء y ثم حل المعادلة الناتجة في x.","En":"Add the equations to eliminate y, then solve for x."}],"Title":{"Ar":"باستخدام الحذف، حل النظام $2x+y=7$ و$x-y=2$. ما قيمة $x$؟","En":"Use elimination to solve $2x+y=7$ and $x-y=2$. What is $x$?"},"Points":10,"Options":[{"LatexCode":"2","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"2 لا يحقق المعادلة الناتجة 3x=9.","En":"Two does not satisfy the resulting equation 3x=9."}},{"LatexCode":"4","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"4 يعطي 12 بدلاً من 9 في المعادلة الناتجة.","En":"Four gives twelve rather than nine in the resulting equation."}},{"LatexCode":"1","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"1 هو قيمة y بعد إيجاد x، لا قيمة x.","En":"One is the value of y after finding x, not x itself."}},{"LatexCode":"3","IsCorrect":true,"ErrorType":"","Reason":null}],"StageId":4,"Question":{"Ar":"باستخدام الحذف، حل النظام $2x+y=7$ و$x-y=2$. ما قيمة $x$؟","En":"Use elimination to solve $2x+y=7$ and $x-y=2$. What is $x$?"},"Solution":{"Idea":{"Ar":"نجمع المعادلتين لحذف المتغير ذي المعاملين المتعاكسين.","En":"Add the equations to eliminate the variable with opposite coefficients."},"Unit":{"Ar":"لا توجد وحدة محددة في السؤال","En":"No unit specified"},"Steps":[{"Ar":"معاملا y متعاكسان؛ نجمع المعادلتين لإلغاء y.","En":"The y coefficients are opposite; add the equations to eliminate y."},{"Ar":"$3x=9$","En":"$3x=9$"},{"Ar":"نقسم المعادلة الناتجة 3x=9 على ثلاثة.","En":"Divide the resulting equation 3x=9 by three."}],"Result":{"Ar":"$3$","En":"$3$"},"CommonError":{"Ar":"لا تجمع معاملات y مع معاملات x؛ اجمع الحدود المتشابهة.","En":"Do not combine unlike x and y terms; add like terms."},"FormulaLatex":"(2x+y)+(x-y)=7+2","Substitution":{"Ar":"$x=3$","En":"$x=3$"},"Verification":{"Ar":"$y=1,\\quad2(3)+1=7,\\quad3-1=2$","En":"$y=1,\\quad2(3)+1=7,\\quad3-1=2$"}},"TrackIds":[18,21],"CategoryId":90,"PrimarySkillId":332,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"لاحظ أن معاملي y في المعادلتين متعاكسان.","En":"Notice the two y coefficients are opposites."},{"Ar":"اجمع المعادلتين لإلغاء y ثم حل المعادلة الناتجة في x.","En":"Add the equations to eliminate y, then solve for x."}],"Solution":{"Idea":{"Ar":"نجمع المعادلتين لحذف المتغير ذي المعاملين المتعاكسين.","En":"Add the equations to eliminate the variable with opposite coefficients."},"Unit":{"Ar":"لا توجد وحدة محددة في السؤال","En":"No unit specified"},"Steps":[{"Ar":"معاملا y متعاكسان؛ نجمع المعادلتين لإلغاء y.","En":"The y coefficients are opposite; add the equations to eliminate y."},{"Ar":"$3x=9$","En":"$3x=9$"},{"Ar":"نقسم المعادلة الناتجة 3x=9 على ثلاثة.","En":"Divide the resulting equation 3x=9 by three."}],"Result":{"Ar":"$3$","En":"$3$"},"CommonError":{"Ar":"لا تجمع معاملات y مع معاملات x؛ اجمع الحدود المتشابهة.","En":"Do not combine unlike x and y terms; add like terms."},"FormulaLatex":"(2x+y)+(x-y)=7+2","Substitution":{"Ar":"$x=3$","En":"$x=3$"},"Verification":{"Ar":"$y=1,\\quad2(3)+1=7,\\quad3-1=2$","En":"$y=1,\\quad2(3)+1=7,\\quad3-1=2$"}},"Distractors":[{"ErrorType":"incorrect-option","Reason":{"Ar":"2 لا يحقق المعادلة الناتجة 3x=9.","En":"Two does not satisfy the resulting equation 3x=9."},"Order":1},{"ErrorType":"incorrect-option","Reason":{"Ar":"4 يعطي 12 بدلاً من 9 في المعادلة الناتجة.","En":"Four gives twelve rather than nine in the resulting equation."},"Order":2},{"ErrorType":"incorrect-option","Reason":{"Ar":"1 هو قيمة y بعد إيجاد x، لا قيمة x.","En":"One is the value of y after finding x, not x itself."},"Order":3},{"ErrorType":"","Reason":null,"Order":4}]}$mw$,$mw$نجمع المعادلتين لحذف المتغير ذي المعاملين المتعاكسين.

$(2x+y)+(x-y)=7+2$

1. معاملا y متعاكسان؛ نجمع المعادلتين لإلغاء y.

2. $3x=9$

3. نقسم المعادلة الناتجة 3x=9 على ثلاثة.

$x=3$

$3$ لا توجد وحدة محددة في السؤال

$y=1,\quad2(3)+1=7,\quad3-1=2$

لا تجمع معاملات y مع معاملات x؛ اجمع الحدود المتشابهة.$mw$,$mw$Add the equations to eliminate the variable with opposite coefficients.

$(2x+y)+(x-y)=7+2$

1. The y coefficients are opposite; add the equations to eliminate y.

2. $3x=9$

3. Divide the resulting equation 3x=9 by three.

$x=3$

$3$ No unit specified

$y=1,\quad2(3)+1=7,\quad3-1=2$

Do not combine unlike x and y terms; add like terms.$mw$),
(878,1634,$mw$578D06007B26501EDE1BD81D899CB7ABB47860AFF5B6D541BB7ADC2571E71E64$mw$,$mw$a6f52c348f3664270b9074b56463339e$mw$,$mw$$mw$,$mw${"Id":1634,"StageId":4,"CategoryId":90,"Points":10,"TitleAr":"للنظام $A=diag(2,3)$ و$b=(4,9)$، إذا كان التقريب $x=(2,2)$، فما معيار اللانهاية للمتبقي $r=b-Ax$؟","TitleEn":"For $A=diag(2,3)$, $b=(4,9)$ and approximate solution $x=(2,2)$, find the infinity norm of residual ","QuestionTextAr":"للنظام $A=diag(2,3)$ و$b=(4,9)$، إذا كان التقريب $x=(2,2)$، فما معيار اللانهاية للمتبقي $r=b-Ax$؟","QuestionTextEn":"For $A=diag(2,3)$, $b=(4,9)$ and approximate solution $x=(2,2)$, find the infinity norm of residual $r=b-Ax$.","DetailedSolutionAr":"القانون المستخدم: متجه الباقي في حل نظام خطي هو r = b − A x̂، ومعيار اللانهاية يساوي أكبر قيمة مطلقة بين مركبات الباقي. المصفوفة A قطرية (2،3) والتقريب x̂=(2،2)، لذا Ax̂=(4،6)، ومع b=(4،9) نجد r=(0،3). إذن ||r||∞=max(|0|،|3|)=3.","DetailedSolutionEn":"Rule used: Residual for an approximate linear-system solution is r = b − Ax̂, and its infinity norm is the largest absolute residual component. With A=diag(2,3), x̂=(2,2), Ax̂=(4,6), and b=(4,9), residual is r=(0,3). Therefore ||r||∞ = max(0,3) = 3.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":6525,"Order":1,"LatexCode":"0","IsCorrect":false},{"Id":6526,"Order":2,"LatexCode":"1","IsCorrect":false},{"Id":6527,"Order":3,"LatexCode":"3","IsCorrect":true},{"Id":6528,"Order":4,"LatexCode":"9","IsCorrect":false}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"المتبقي هو المتجه b−Ax.","En":"The residual vector is b−Ax."},{"Ar":"احسب مركبتي المتبقي ثم اختر أكبر قيمة مطلقة بينهما.","En":"Find both residual components and take the largest absolute value."}],"Title":{"Ar":"للنظام $A=diag(2,3)$ و$b=(4,9)$، إذا كان التقريب $x=(2,2)$، فما معيار اللانهاية للمتبقي $r=b-Ax$؟","En":"For $A=diag(2,3)$, $b=(4,9)$ and approximate solution $x=(2,2)$, find the infinity norm of residual "},"Points":10,"Options":[{"LatexCode":"0","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"0 يتجاهل المركبة الثانية للمتبقي.","En":"Zero ignores the second residual component."}},{"LatexCode":"1","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"1 لا يساوي أكبر مقدار للمركبتين 0 و3.","En":"One is not the largest magnitude of zero and three."}},{"LatexCode":"3","IsCorrect":true,"ErrorType":"","Reason":null},{"LatexCode":"9","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"9 قيمة المركبة الثانية من b لا المتبقي.","En":"Nine is the second component of b, not the residual."}}],"StageId":4,"Question":{"Ar":"للنظام $A=diag(2,3)$ و$b=(4,9)$، إذا كان التقريب $x=(2,2)$، فما معيار اللانهاية للمتبقي $r=b-Ax$؟","En":"For $A=diag(2,3)$, $b=(4,9)$ and approximate solution $x=(2,2)$, find the infinity norm of residual $r=b-Ax$."},"Solution":{"Idea":{"Ar":"الباقي هو b−Ax؛ معيار اللانهاية أكبر مقدار لمركباته.","En":"The residual is b−Ax; its infinity norm is the largest component magnitude."},"Unit":{"Ar":"لا توجد وحدة محددة في السؤال","En":"No unit specified"},"Steps":[{"Ar":"نضرب المصفوفة القطرية في متجه التقريب، فتضرب كل مركبة بمعاملها القطري.","En":"Multiply the diagonal matrix by the approximate vector, scaling each component by its diagonal entry."},{"Ar":"$Ax=(4,6),\\quad r=(4,9)-(4,6)=(0,3)$","En":"$Ax=(4,6),\\quad r=(4,9)-(4,6)=(0,3)$"},{"Ar":"نطرح الناتج من b، ثم نأخذ أكبر قيمة مطلقة للمركبتين.","En":"Subtract from b, then take the largest absolute component."}],"Result":{"Ar":"$3$","En":"$3$"},"CommonError":{"Ar":"لا تحسب معيار b بدلاً من معيار المتبقي.","En":"Do not compute the norm of b instead of the residual."},"FormulaLatex":"r=b-Ax,\\quad\\|r\\|_\\infty=\\max_i|r_i|","Substitution":{"Ar":"$\\|r\\|_\\infty=\\max(0,3)=3$","En":"$\\|r\\|_\\infty=\\max(0,3)=3$"},"Verification":{"Ar":"$Ax+r=(4,6)+(0,3)=(4,9)=b$","En":"$Ax+r=(4,6)+(0,3)=(4,9)=b$"}},"TrackIds":[18,21],"CategoryId":90,"PrimarySkillId":332,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"المتبقي هو المتجه b−Ax.","En":"The residual vector is b−Ax."},{"Ar":"احسب مركبتي المتبقي ثم اختر أكبر قيمة مطلقة بينهما.","En":"Find both residual components and take the largest absolute value."}],"Solution":{"Idea":{"Ar":"الباقي هو b−Ax؛ معيار اللانهاية أكبر مقدار لمركباته.","En":"The residual is b−Ax; its infinity norm is the largest component magnitude."},"Unit":{"Ar":"لا توجد وحدة محددة في السؤال","En":"No unit specified"},"Steps":[{"Ar":"نضرب المصفوفة القطرية في متجه التقريب، فتضرب كل مركبة بمعاملها القطري.","En":"Multiply the diagonal matrix by the approximate vector, scaling each component by its diagonal entry."},{"Ar":"$Ax=(4,6),\\quad r=(4,9)-(4,6)=(0,3)$","En":"$Ax=(4,6),\\quad r=(4,9)-(4,6)=(0,3)$"},{"Ar":"نطرح الناتج من b، ثم نأخذ أكبر قيمة مطلقة للمركبتين.","En":"Subtract from b, then take the largest absolute component."}],"Result":{"Ar":"$3$","En":"$3$"},"CommonError":{"Ar":"لا تحسب معيار b بدلاً من معيار المتبقي.","En":"Do not compute the norm of b instead of the residual."},"FormulaLatex":"r=b-Ax,\\quad\\|r\\|_\\infty=\\max_i|r_i|","Substitution":{"Ar":"$\\|r\\|_\\infty=\\max(0,3)=3$","En":"$\\|r\\|_\\infty=\\max(0,3)=3$"},"Verification":{"Ar":"$Ax+r=(4,6)+(0,3)=(4,9)=b$","En":"$Ax+r=(4,6)+(0,3)=(4,9)=b$"}},"Distractors":[{"ErrorType":"incorrect-option","Reason":{"Ar":"0 يتجاهل المركبة الثانية للمتبقي.","En":"Zero ignores the second residual component."},"Order":1},{"ErrorType":"incorrect-option","Reason":{"Ar":"1 لا يساوي أكبر مقدار للمركبتين 0 و3.","En":"One is not the largest magnitude of zero and three."},"Order":2},{"ErrorType":"","Reason":null,"Order":3},{"ErrorType":"incorrect-option","Reason":{"Ar":"9 قيمة المركبة الثانية من b لا المتبقي.","En":"Nine is the second component of b, not the residual."},"Order":4}]}$mw$,$mw$الباقي هو b−Ax؛ معيار اللانهاية أكبر مقدار لمركباته.

$r=b-Ax,\quad\|r\|_\infty=\max_i|r_i|$

1. نضرب المصفوفة القطرية في متجه التقريب، فتضرب كل مركبة بمعاملها القطري.

2. $Ax=(4,6),\quad r=(4,9)-(4,6)=(0,3)$

3. نطرح الناتج من b، ثم نأخذ أكبر قيمة مطلقة للمركبتين.

$\|r\|_\infty=\max(0,3)=3$

$3$ لا توجد وحدة محددة في السؤال

$Ax+r=(4,6)+(0,3)=(4,9)=b$

لا تحسب معيار b بدلاً من معيار المتبقي.$mw$,$mw$The residual is b−Ax; its infinity norm is the largest component magnitude.

$r=b-Ax,\quad\|r\|_\infty=\max_i|r_i|$

1. Multiply the diagonal matrix by the approximate vector, scaling each component by its diagonal entry.

2. $Ax=(4,6),\quad r=(4,9)-(4,6)=(0,3)$

3. Subtract from b, then take the largest absolute component.

$\|r\|_\infty=\max(0,3)=3$

$3$ No unit specified

$Ax+r=(4,6)+(0,3)=(4,9)=b$

Do not compute the norm of b instead of the residual.$mw$);
DO $audit$
DECLARE b record; d "CurriculumDraftItems"%ROWTYPE; p "Problems"%ROWTYPE; tr int; sk int; n int; actor int;
BEGIN
 FOR b IN SELECT * FROM reviewed_batch ORDER BY source LOOP
  PERFORM pg_advisory_xact_lock(-b.source::bigint);
  SELECT * INTO STRICT d FROM "CurriculumDraftItems" WHERE "Id"=b.draft FOR UPDATE;
  SELECT * INTO STRICT p FROM "Problems" WHERE "Id"=b.source FOR UPDATE;
  PERFORM 1 FROM "QuestionOptions" WHERE "ProblemId"=b.source FOR UPDATE;
  actor:=d."OwnerUserId"; tr:=(b.wizard->'TrackIds'->>0)::int; sk:=(b.wizard->>'PrimarySkillId')::int;
  IF d."SourceProblemId" IS DISTINCT FROM b.source OR d."Revision"<>0 OR d."EditorialStatus"<>'Draft' OR d."PublishedProblemId" IS NOT NULL OR d."SourceFingerprint" IS DISTINCT FROM b.fp OR md5(d."WizardJson") IS DISTINCT FROM b.draft_hash OR upper(encode(sha256(decode(b.source_hex,'hex')),'hex'))<>b.fp OR (SELECT json_build_object('Id',pp."Id",'StageId',pp."StageId",'CategoryId',pp."CategoryId",'Points',pp."Points",'TitleAr',pp."TitleAr",'TitleEn',pp."TitleEn",'QuestionTextAr',pp."QuestionTextAr",'QuestionTextEn',pp."QuestionTextEn",'DetailedSolutionAr',pp."DetailedSolutionAr",'DetailedSolutionEn',pp."DetailedSolutionEn",'YoutubeSolutionUrl',pp."YoutubeSolutionUrl",'EditorialDetailsJson',pp."EditorialDetailsJson",'Options',(select json_agg(json_build_object('Id',o."Id",'Order',o."Order",'LatexCode',o."LatexCode",'IsCorrect',o."IsCorrect") order by o."Order",o."Id") from "QuestionOptions" o where o."ProblemId"=pp."Id"))::jsonb FROM "Problems" pp WHERE pp."Id"=b.source) IS DISTINCT FROM b.snapshot THEN RAISE EXCEPTION 'Source/draft conflict: %',b.draft; END IF;
  IF NOT EXISTS(SELECT 1 FROM "Users" WHERE "Id"=actor AND "Role"='Admin' AND "IsActive" AND NOT "StaffSetupPending") OR (SELECT count(*) FROM "CurriculumDraftItems" WHERE "SourceProblemId"=b.source AND "EditorialStatus" NOT IN ('Published','Withdrawn'))<>1 THEN RAISE EXCEPTION 'Owner/open-draft conflict: %',b.draft; END IF;
  PERFORM 1 FROM "LearningTracks" WHERE "Id" IN (SELECT jsonb_array_elements_text(b.wizard->'TrackIds')::int) ORDER BY "Id" FOR UPDATE;
  IF NOT EXISTS(SELECT 1 FROM "LearningTracks" WHERE "Id"=tr AND "StageId"=p."StageId" AND "IsPublished" AND "Revision"<2147483647) OR NOT EXISTS(SELECT 1 FROM "Categories" WHERE "Id"=p."CategoryId" AND "StageId"=p."StageId") OR NOT EXISTS(SELECT 1 FROM "CurriculumSkills" s JOIN "CurriculumDomains" dm ON dm."Id"=s."DomainId" WHERE s."Id"=sk AND s."StageId"=p."StageId" AND s."CategoryId"=p."CategoryId" AND s."IsPublished" AND dm."IsPublished") OR NOT EXISTS(SELECT 1 FROM "LearningTrackCategories" WHERE "TrackId"=tr AND "CategoryId"=p."CategoryId") OR NOT EXISTS(SELECT 1 FROM "LearningTrackSkills" WHERE "TrackId"=tr AND "SkillId"=sk) OR (SELECT array_agg("TrackId" ORDER BY "TrackId") FROM "LearningTrackProblems" WHERE "ProblemId"=b.source) IS DISTINCT FROM ARRAY(SELECT jsonb_array_elements_text(b.wizard->'TrackIds')::int ORDER BY 1) OR (SELECT array_agg("SkillId" ORDER BY "SkillId") FROM "CurriculumProblemSkills" WHERE "ProblemId"=b.source) IS DISTINCT FROM ARRAY[sk] OR NOT EXISTS(SELECT 1 FROM "CurriculumProblemSkills" WHERE "ProblemId"=b.source AND "SkillId"=sk AND "IsPrimary") OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(b.wizard->'TrackIds') j(id) LEFT JOIN "LearningTracks" lt ON lt."Id"=j.id::int WHERE lt."Id" IS NULL OR lt."StageId"<>p."StageId" OR lt."Revision">=2147483647 OR NOT EXISTS(SELECT 1 FROM "LearningTrackCategories" WHERE "TrackId"=lt."Id" AND "CategoryId"=p."CategoryId") OR NOT EXISTS(SELECT 1 FROM "LearningTrackSkills" WHERE "TrackId"=lt."Id" AND "SkillId"=sk)) THEN RAISE EXCEPTION 'Scope conflict: %',b.draft; END IF;
  IF EXISTS(SELECT 1 FROM "Problems" q WHERE q."Id"<>b.source AND q."StageId"=p."StageId" AND (upper(regexp_replace(btrim(q."QuestionTextAr"),'[[:space:]]+',' ','g'))=upper(regexp_replace(btrim(p."QuestionTextAr"),'[[:space:]]+',' ','g')) OR upper(regexp_replace(btrim(q."QuestionTextEn"),'[[:space:]]+',' ','g'))=upper(regexp_replace(btrim(p."QuestionTextEn"),'[[:space:]]+',' ','g')))) THEN RAISE EXCEPTION 'Duplicate: %',b.draft; END IF;
  IF EXISTS(SELECT 1 FROM "CurriculumDraftItems" x WHERE x."Id"<>b.draft AND x."EditorialStatus" NOT IN ('Published','Withdrawn') AND (x."WizardJson"::jsonb#>>'{Question,Ar}'=p."QuestionTextAr" OR x."WizardJson"::jsonb#>>'{Question,En}'=p."QuestionTextEn")) THEN RAISE EXCEPTION 'Open draft duplicate: %',b.draft; END IF;
  IF b.wizard#>>'{Question,Ar}' IS DISTINCT FROM p."QuestionTextAr" OR b.wizard#>>'{Question,En}' IS DISTINCT FROM p."QuestionTextEn" OR length(b.flat_ar)>12000 OR length(b.flat_en)>12000 THEN RAISE EXCEPTION 'Question/length conflict: %',b.draft; END IF;
  UPDATE "Problems" SET "TitleAr"=b.wizard#>>'{Title,Ar}',"TitleEn"=b.wizard#>>'{Title,En}',"DetailedSolutionAr"=b.flat_ar,"DetailedSolutionEn"=b.flat_en,"EditorialDetailsJson"=b.metadata WHERE "Id"=b.source;
  UPDATE "CurriculumDraftItems" SET "WizardJson"=b.wizard::text,"EditorialStatus"='Published',"Revision"=4,"SubmittedAtUtc"=now(),"ReviewedAtUtc"=now(),"ReviewedByUserId"=actor,"ReviewNote"='Owner-authorized SQL maintenance; AI educational review and source-locked verification. Existing draft owner recorded for attribution; no API login.',"PublishedAtUtc"=now(),"PublishedProblemId"=b.source WHERE "Id"=b.draft;
  UPDATE "LearningTracks" SET "Revision"="Revision"+1 WHERE "Id" IN (SELECT jsonb_array_elements_text(b.wizard->'TrackIds')::int);
  INSERT INTO "PlatformActivityEvents"("ActorUserId","ActorRole","Action","Resource","ResourceId","Origin","CreatedAtUtc") SELECT actor,'Admin',action,'EditorialProblem',b.draft::text,'owner_sql',now() FROM unnest(ARRAY['EditorialDraftEdited','EditorialDraftSubmitted','EditorialDraftApproved','EditorialAmendmentPublished']) action;
 END LOOP;
END $audit$;
COMMIT;
